    ko: '보관',
    ar: 'أرشفة',
    pt: 'Arquivar',
    fi: 'Arkistoi',
    is: 'Setja í geymslu',
    sk: 'Archivovať',
    sl: 'Arhiviraj',
    hu: 'Archiválás',
    ro: 'Arhivează',
    bg: 'Архивирай',
    hr: 'Arhiviraj',
