    pt: 'Uma implementação está bloqueada (#{id}, {status}). Bloqueia todas as seguintes — o documento 21 §8 explica como a libertar.',
    fi: 'Julkaisu on jumissa (#{id}, {status}). Se estää kaikki seuraavat — dokumentin 21 §8 kertoo, miten se vapautetaan.',
    is: 'Útgáfa situr föst (#{id}, {status}). Hún hindrar allar frekari — skjal 21 §8 segir hvernig á að losa hana.',
    sk: 'Nasadenie viazne (#{id}, {status}). Blokuje každé ďalšie — dokument 21 §8 hovorí, ako ho uvoľniť.',
    sl: 'Uvajanje se je zataknilo (#{id}, {status}). Blokira vsako nadaljnje — dokument 21 §8 pove, kako ga sprostiti.',
    hu: 'Egy telepítés elakadt (#{id}, {status}). Minden további telepítést blokkol — a 21. dokumentum 8. §-a leírja, hogyan lehet feloldani.',
    ro: 'O implementare este blocată (#{id}, {status}). Ea blochează orice altă implementare — documentul 21 §8 explică cum se deblochează.',
