  // ------------------------------------------------- Absenderdomains
  'admin.pay.intro': {
    de: 'Der Stripe-Zugang der Plattform. Mit ihm verbinden die Häuser ihr eigenes Stripe-Konto für Zahlungslinks. Geheime Werte werden verschlüsselt gespeichert und nicht wieder angezeigt.',
    en: 'The platform’s Stripe access. Properties use it to connect their own Stripe account for payment links. Secret values are stored encrypted and never shown again.',
    tr: 'Platformun Stripe erişimi. Tesisler ödeme bağlantıları için kendi Stripe hesaplarını bununla bağlar. Gizli değerler şifreli saklanır ve bir daha gösterilmez.',
    nl: 'De Stripe-toegang van het platform. Hiermee koppelen hotels hun eigen Stripe-account voor betaallinks. Geheime waarden worden versleuteld opgeslagen en niet meer getoond.',
    da: 'Platformens Stripe-adgang. Med den forbinder hotellerne deres egen Stripe-konto til betalingslinks. Hemmelige værdier gemmes krypteret og vises ikke igen.',
    sv: 'Plattformens Stripe-åtkomst. Med den kopplar hotellen sitt eget Stripe-konto för betallänkar. Hemliga värden lagras krypterade och visas aldrig igen.',
    nb: 'Plattformens Stripe-tilgang. Med den kobler hotellene sin egen Stripe-konto til betalingslenker. Hemmelige verdier lagres kryptert og vises ikke igjen.',
    cs: 'Přístup platformy ke Stripe. Hotely přes něj propojují vlastní účet Stripe pro platební odkazy. Tajné hodnoty se ukládají šifrovaně a už se nezobrazí.',
    fr: 'L’accès Stripe de la plateforme. Les établissements l’utilisent pour connecter leur propre compte Stripe aux liens de paiement. Les valeurs secrètes sont chiffrées et ne sont plus affichées.',
    it: 'L’accesso Stripe della piattaforma. Le strutture lo usano per collegare il proprio account Stripe ai link di pagamento. I valori segreti sono salvati cifrati e non vengono più mostrati.',
    es: 'El acceso a Stripe de la plataforma. Con él, los alojamientos conectan su propia cuenta de Stripe para los enlaces de pago. Los valores secretos se guardan cifrados y no se vuelven a mostrar.',
    ru: 'Доступ платформы к Stripe. Через него объекты подключают собственный аккаунт Stripe для платёжных ссылок. Секретные значения хранятся в зашифрованном виде и больше не показываются.',
    pl: 'Dostęp platformy do Stripe. Dzięki niemu obiekty łączą własne konto Stripe dla linków płatności. Wartości tajne są zapisywane w postaci zaszyfrowanej i nie są ponownie wyświetlane.',
    uk: 'Доступ платформи до Stripe. Через нього об’єкти підключають власний обліковий запис Stripe для платіжних посилань. Секретні значення зберігаються зашифрованими й більше не показуються.',
    zh: '平台的 Stripe 访问凭据。各酒店通过它连接自己的 Stripe 账户以使用付款链接。机密值加密存储，保存后不再显示。',
    ko: '플랫폼의 Stripe 접근 정보입니다. 각 숙소는 이를 통해 결제 링크용 자체 Stripe 계정을 연결합니다. 비밀 값은 암호화되어 저장되며 다시 표시되지 않습니다.',
    ar: 'وصول المنصة إلى Stripe. تربط المنشآت من خلاله حساب Stripe الخاص بها لروابط الدفع. تُخزَّن القيم السرية مشفّرة ولا تُعرض مرة أخرى.',
    pt: 'O acesso Stripe da plataforma. Com ele, os alojamentos ligam a sua própria conta Stripe para links de pagamento. Os valores secretos são guardados encriptados e não voltam a ser mostrados.',
    fi: 'Alustan Stripe-yhteys. Sen avulla majoituspaikat yhdistävät oman Stripe-tilinsä maksulinkkejä varten. Salaiset arvot tallennetaan salattuina eikä niitä näytetä uudelleen.',
    is: 'Stripe-aðgangur kerfisins. Með honum tengja gististaðir eigin Stripe-reikning fyrir greiðslutengla. Leynigildi eru vistuð dulkóðuð og aldrei sýnd aftur.',
    sk: 'Prístup platformy k Stripe. Hotely cez neho prepájajú vlastný účet Stripe pre platobné odkazy. Tajné hodnoty sa ukladajú šifrovane a už sa nezobrazia.',
    sl: 'Dostop platforme do Stripe. Z njim nastanitve povežejo lasten račun Stripe za plačilne povezave. Skrivne vrednosti so shranjene šifrirano in se ne prikažejo več.',
    hu: 'A platform Stripe-hozzáférése. Ezzel kapcsolják a szálláshelyek saját Stripe-fiókjukat a fizetési linkekhez. A titkos értékek titkosítva tárolódnak, és többé nem jelennek meg.',
    ro: 'Accesul platformei la Stripe. Prin el, unitățile își conectează propriul cont Stripe pentru linkurile de plată. Valorile secrete sunt stocate criptat și nu mai sunt afișate.',
    bg: 'Достъпът на платформата до Stripe. Чрез него обектите свързват собствения си акаунт в Stripe за линкове за плащане. Тайните стойности се съхраняват криптирани и не се показват отново.',
    hr: 'Pristup platforme Stripeu. Preko njega objekti povezuju vlastiti Stripe račun za poveznice za plaćanje. Tajne vrijednosti spremaju se šifrirano i više se ne prikazuju.',
    sr: 'Pristup platforme Stripe-u. Preko njega objekti povezuju sopstveni Stripe nalog za linkove za plaćanje. Tajne vrednosti čuvaju se šifrovano i više se ne prikazuju.',
    mk: 'Пристапот на платформата до Stripe. Преку него објектите ја поврзуваат сопствената Stripe сметка за линкови за плаќање. Тајните вредности се чуваат шифрирани и не се прикажуваат повторно.',
    sq: 'Qasja e platformës në Stripe. Me të, strukturat lidhin llogarinë e tyre Stripe për lidhjet e pagesës. Vlerat sekrete ruhen të enkriptuara dhe nuk shfaqen më.',
    el: 'Η πρόσβαση της πλατφόρμας στο Stripe. Μέσω αυτής τα καταλύματα συνδέουν τον δικό τους λογαριασμό Stripe για συνδέσμους πληρωμής. Οι μυστικές τιμές αποθηκεύονται κρυπτογραφημένες και δεν εμφανίζονται ξανά.',
    lt: 'Platformos prieiga prie Stripe. Per ją apgyvendinimo įstaigos prijungia savo Stripe paskyrą mokėjimo nuorodoms. Slaptos reikšmės saugomos užšifruotos ir daugiau nerodomos.',
    lv: 'Platformas piekļuve Stripe. Ar to naktsmītnes savieno savu Stripe kontu maksājumu saitēm. Slepenās vērtības tiek glabātas šifrētas un vairs netiek rādītas.',
    et: 'Platvormi Stripe’i ligipääs. Selle kaudu ühendavad majutusasutused oma Stripe’i konto makselinkide jaoks. Salajased väärtused salvestatakse krüpteeritult ja neid enam ei näidata.' },
